beforeExample:
package test;

import org.eclipse.jdt.annotation.NonNullByDefault;

@NonNullByDefault
public class MyClass {
    @org.eclipse.jdt.annotation.NonNullByDefault // This method annotation is redundant
    public String myMethod(String param) {
        return "value";
    }

    // Another method which should not be affected
    public void anotherMethod() {
        System.out.println("Hello");
    }

    // An inner class, its methods should not be affected by outer class's @NonNullByDefault
    @NonNullByDefault
    public static class InnerClass {
        public String innerMethod() { return "inner"; }
    }
}

