negativeExample:
package test;

import org.eclipse.jdt.annotation.NonNullByDefault;

public class MyClass { // No @NonNullByDefault on the class itself
    @org.eclipse.jdt.annotation.NonNullByDefault // This method annotation is NOT redundant here
    public String myMethod(String param) {
        return "value";
    }

    // Another method which should not be affected
    public void anotherMethod() {
        System.out.println("Hello");
    }

    // An inner class with its own @NonNullByDefault
    @NonNullByDefault
    public static class InnerClass {
        @org.eclipse.jdt.annotation.NonNullByDefault // Redundant relative to InnerClass, but not MyClass
        public String innerMethod() { return "inner"; }
    }
}
